"use client";

import { useState } from "react";

import { Canvas } from "./canvas";
import { sampleDocuments, sampleFolders } from "./canvas-board-data";
import { CanvasCard } from "./canvas-card";
import { DocumentOverlay } from "./document-overlay";
import { DocumentPreview } from "./document-preview";
import { FolderCard } from "./folder-card";
import { Pagination } from "./pagination";

interface OpenedDoc {
  id: string;
  title: string;
  sourceRect: DOMRect | null;
}

const findSiblings = (id: string) => {
  for (const folder of sampleFolders) {
    const index = folder.items.findIndex((item) => item.id === id);
    if (index !== -1) {
      return {
        next: folder.items[index + 1] ?? null,
        prev: folder.items[index - 1] ?? null,
      };
    }
  }
  return { next: null, prev: null };
};

/**
 * A self-contained demo composing the canvas primitives: a pan/zoom Canvas with
 * draggable folder cards that peek open into a masonry of preview cards, and a
 * document overlay that scales a card up into a full-screen reader and back.
 * Drop it anywhere, it renders full-bleed (the Canvas is fixed inset-0).
 */
export const CanvasBoard = () => {
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [peekedFolder, setPeekedFolder] = useState<string | null>(null);
  const [opened, setOpened] = useState<OpenedDoc | null>(null);

  const openId = opened?.id;
  const { next, prev } = openId
    ? findSiblings(openId)
    : { next: null, prev: null };

  return (
    <>
      <Canvas
        initialScale={0.75}
        initialX={80}
        initialY={40}
        onSelect={(ids) => setSelected(new Set(ids))}
      >
        <CanvasCard
          cardId="hero"
          dimmed={peekedFolder !== null}
          selected={selected.has("hero")}
          width={300}
          x={120}
          y={-40}
        >
          <div className="p-5">
            <h2 className="font-semibold text-canvas-fg text-sm">Canvas Kit</h2>
            <p className="mt-1.5 text-canvas-fg/55 text-xs leading-relaxed">
              Pan with two fingers or scroll. Pinch or ⌘+scroll to zoom. Drag
              the folders, click to peek, then open a card to read it.
              Drag-select to marquee.
            </p>
          </div>
        </CanvasCard>

        {sampleFolders.map((folder) => (
          <FolderCard
            dimmed={peekedFolder !== null && peekedFolder !== folder.id}
            folderId={folder.id}
            initialPeeked={peekedFolder === folder.id}
            items={folder.items}
            key={folder.id}
            onOpenItem={(state) =>
              setOpened({
                id: state.itemId,
                sourceRect: state.sourceRect,
                title: state.title,
              })
            }
            onPeekChange={(open) => setPeekedFolder(open ? folder.id : null)}
            openItemId={
              openId && folder.items.some((item) => item.id === openId)
                ? openId
                : undefined
            }
            renderPreview={(item, ctx) => (
              <DocumentPreview
                height={ctx.height}
                itemId={item.id}
                title={item.title}
                width={ctx.width}
              />
            )}
            selected={selected.has(folder.id)}
            title={folder.title}
            x={folder.x}
            y={folder.y}
          />
        ))}
      </Canvas>

      <DocumentOverlay
        footer={
          <Pagination
            className="mx-auto max-w-2xl"
            next={
              next
                ? {
                    onClick: () =>
                      setOpened({
                        id: next.id,
                        sourceRect: null,
                        title: next.title,
                      }),
                    title: next.title,
                  }
                : null
            }
            previous={
              prev
                ? {
                    onClick: () =>
                      setOpened({
                        id: prev.id,
                        sourceRect: null,
                        title: prev.title,
                      }),
                    title: prev.title,
                  }
                : null
            }
          />
        }
        onClose={() => setOpened(null)}
        open={!!opened}
        sourceId={openId}
        sourceRect={opened?.sourceRect}
        title={opened?.title}
      >
        {openId ? <p>{sampleDocuments[openId]?.body}</p> : null}
      </DocumentOverlay>
    </>
  );
};

import type { CanvasFolderItem } from "./folder-card";

export interface CanvasBoardFolder {
  id: string;
  title: string;
  x: number;
  y: number;
  items: CanvasFolderItem[];
}

const makeItems = (prefix: string, titles: string[]): CanvasFolderItem[] =>
  titles.map((title, i) => ({
    completed: i % 3 === 0,
    id: `${prefix}-${i}`,
    title,
  }));

export const sampleFolders: CanvasBoardFolder[] = [
  {
    id: "foundations",
    items: makeItems("foundations", [
      "Layout & grids",
      "Spacing systems",
      "Color & contrast",
      "Visual hierarchy",
    ]),
    title: "Foundations",
    x: 120,
    y: 200,
  },
  {
    id: "typography",
    items: makeItems("typography", [
      "Type scale",
      "Line length",
      "Rhythm",
      "Pairing fonts",
      "Optical sizing",
    ]),
    title: "Typography",
    x: 520,
    y: 320,
  },
  {
    id: "motion",
    items: makeItems("motion", [
      "Easing curves",
      "Choreography",
      "Spatial continuity",
    ]),
    title: "Motion",
    x: 920,
    y: 180,
  },
];

const makeBody = (title: string): string =>
  `${title} is one of the building blocks of the craft. This is sample content for the Canvas Kit demo, install the registry to wire your own documents into the overlay. Pan the canvas, peek a folder, and open any card to read it full-screen; the back arrow scales it right back into the card it came from.`;

/** Sample document bodies for the board demo, keyed by folder item id. */
export const sampleDocuments: Record<string, { body: string; title: string }> =
  Object.fromEntries(
    sampleFolders.flatMap((folder) =>
      folder.items.map((item) => [
        item.id,
        { body: makeBody(item.title), title: item.title },
      ])
    )
  );

"use client";

import { sampleDocuments } from "./canvas-board-data";

/** Width the overlay renders content at; the preview is this scaled down. */
const INNER_WIDTH = 640;

interface DocumentPreviewProps {
  /** Folder item id, used to look up the document body. */
  itemId: string;
  title: string;
  width: number;
  height: number;
}

/**
 * A miniature of the document that opens in the overlay, the real title and
 * body scaled down, so a peeked card reads as a page, not a coloured tile.
 */
export const DocumentPreview = ({
  itemId,
  title,
  width,
  height,
}: DocumentPreviewProps) => {
  const doc = sampleDocuments[itemId];
  const scale = width / INNER_WIDTH;

  return (
    <div className="overflow-hidden bg-background" style={{ height, width }}>
      <div
        className="pointer-events-none origin-top-left"
        style={{ transform: `scale(${scale})`, width: INNER_WIDTH }}
      >
        <div className="px-10 py-12">
          <h1 className="mb-6 font-heading font-semibold text-4xl text-canvas-fg tracking-tight">
            {title}
          </h1>
          <p className="text-2xl text-canvas-fg/70 leading-relaxed">
            {doc?.body}
          </p>
        </div>
      </div>
    </div>
  );
};
